const btn = (label: string, onclick: () => void, cls = 'btn', disabled = false) => h('button', { class: cls, onclick, disabled: disabled || undefined }, label);
const gold = (n: number | bigint) => h('span', { class: 'gold' }, `● ${fmt(n)}`);
const sel: Record<string, string | null> = {};

